// Original collection tools use only the actual branch's source-verified stock.
export const hasCollectionDesk=st=>st?.collectionEdition===37&&st.count>0;
export const hasLoungeBench=st=>!!st&&(hasCollectionDesk(st)||!st.count&&!['food','service','visitor','entertainment','auto','gallery'].includes(st.businessKind));
export const collectionProducts=st=>hasCollectionDesk(st)?st.products.filter(p=>p.modelId?.startsWith('v37-real-')):[];
export function collectionSelection(st,selected,id){
 const valid=new Set(collectionProducts(st).map(p=>p.id)),next=[...new Set(selected.filter(v=>valid.has(v)))].slice(0,2);
 if(!valid.has(id))return next;
 if(next.includes(id))return next.filter(v=>v!==id);
 return next.length<2?[...next,id]:next;
}
export function collectionGuideHTML(s,st,selected,{E,esc,picture}){
 const products=collectionProducts(st),chosen=products.filter(p=>selected.includes(p.id));
 const card=(p,comparison=false)=>`<article class="collection-card"><div class="product-art">${picture(p,{mini:true})}</div><h3>${esc(p.name)}</h3><p><strong>${esc(p.colorName)}</strong> · ${esc(p.brand)}</p><dl><dt>Current game price</dt><dd>${E.money(E.price(s,p))} · ${E.money(E.price(s,p)+Math.round(E.price(s,p)*E.TAX))} with tax</dd><dt>Published USD reference</dt><dd>${E.money(Math.round(p.referenceAmount*100))} · checked ${esc(p.referenceCheckedOn)}</dd><dt>Source size labels</dt><dd>${p.sizes.length>12?`<details><summary>${p.sizes.length} official size labels</summary><p>${p.sizes.map(esc).join(' · ')}</p></details>`:p.sizes.map(esc).join(' · ')}</dd><dt>Material notes</dt><dd>${esc(p.material)}</dd></dl><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Official product & selected color ↗</a><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">Inspect / choose size</button>${comparison?'':`<button class="button secondary wide" data-action="collection-pick" data-id="${esc(p.id)}" aria-pressed="${selected.includes(p.id)}" ${selected.length>=2&&!selected.includes(p.id)?'disabled':''}>${selected.includes(p.id)?'Remove from comparison':'Compare this product'}</button>`}</article>`;
 return `<div class="modal-body collection-desk"><span class="eyebrow">VERIFIED COLLECTION · ORIGINAL MALLSIDE STUDIO</span><h3>Get to know the collection.</h3><p>Compare two photographed products, check the source color and size labels, then inspect or try them at this shop. Online references can change; game prices, fit, quantities and returns are simulated.</p><div class="collection-tools"><button class="button orange" data-action="shop-plan-open" data-id="${esc(st.id)}">Build a shopping shortlist</button><button class="button secondary" data-action="plan-notebook">My shortlists</button></div><p class="hint">Comparing here is free. It pauses time, spends no stamina and reserves no stock. Read label and Try use their displayed game time.</p><section id="collection-comparison" aria-label="Product comparison" tabindex="-1"><p class="collection-tally" role="status">${chosen.length}/2 products selected${chosen.length===2?' · ready to compare':chosen.length?' · choose one more below':' · choose products below'}</p>${chosen.length?`<div class="collection-comparison">${chosen.map(p=>card(p,true)).join('')}</div><button class="text-button" data-action="collection-clear">Clear comparison</button>`:''}</section><h3>Explore ${esc(st.name)} · ${products.length} verified models</h3><div class="collection-products">${products.map(p=>card(p)).join('')}</div><button class="button secondary" data-action="back-store">Browse all shop items</button></div>`;
}
